    if not payload_param:
        return jsonify({"error": "Missing 'payload' parameter"}), 400

    try:
        # ペイロードを YAML として解析
        payload = yaml.safe_load(payload_param)
    except yaml.YAMLError as e:
        return jsonify({"error": f"Invalid YAML in payload: {str(e)}"}), 400

    # ペイロードに 'type' キーがあるか確認
    if not payload or 'type' not in payload:
        return jsonify({"error": "Missing 'type' in payload"}), 400

    # 'type' が 'Create' かどうかを確認
    if payload['type'] == 'Create':
        return jsonify({"error": "Type 'Create' is not allowed"}), 400

    # それ以外の場合は、ペイロードを JSON として解析して返す
    try:
        json_payload = json.loads(payload_param)
        return jsonify(json_payload), 200
    except json.JSONDecodeError as e:
        return jsonify({"error": f"Invalid JSON in payload: {str(e)}"}), 400

